export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window required to open the circuit. */
  threshold: number;
  /** Length of the sliding failure window, in milliseconds. */
  windowMs: number;
  /** Time spent open before a single probe is allowed, in milliseconds. */
  cooldownMs: number;
  /** Injectable monotonic-enough clock. The default is Date.now. */
  now?: () => number;
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failuresInWindow: number;
  probeInFlight: boolean;
  openedAt?: number;
  nextProbeAt?: number;
}

/**
 * A small, deterministic circuit breaker for exceptional request rates.
 *
 * It is deliberately a rate boundary only. It does not implement or relax
 * SSRF, loop detection, approval, budget, or any other authorization policy.
 */
export class RateCircuitBreaker {
  private readonly threshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly clock: () => number;
  private stateValue: RateCircuitBreakerState = "closed";
  private failures: number[] = [];
  private openedAtValue?: number;
  private probeInFlightValue = false;

  public constructor(options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.threshold) || options.threshold <= 0) {
      throw new Error("threshold must be a positive finite number");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs < 0) {
      throw new Error("windowMs must be a non-negative finite number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new Error("cooldownMs must be a non-negative finite number");
    }
    this.threshold = options.threshold;
    this.windowMs = options.windowMs;
    this.cooldownMs = options.cooldownMs;
    this.clock = options.now ?? Date.now;
  }

  public get state(): RateCircuitBreakerState {
    this.refreshState();
    return this.stateValue;
  }

  public get isOpen(): boolean {
    return this.state === "open";
  }

  public get isProbeInFlight(): boolean {
    this.refreshState();
    return this.probeInFlightValue;
  }

  /**
   * Reserve capacity for one request. A false result means the request must
   * not be executed and must not have any downstream effect.
   */
  public allowRequest(): boolean {
    this.refreshState();
    if (this.stateValue === "open") {
      return false;
    }
    if (this.stateValue === "half-open") {
      if (this.probeInFlightValue) {
        return false;
      }
      this.probeInFlightValue = true;
      return true;
    }
    return true;
  }

  /** Alias useful to callers that use a preflight/check vocabulary. */
  public beforeRequest(): boolean {
    return this.allowRequest();
  }

  /** Record a successful request. Only a successful half-open probe closes it. */
  public recordSuccess(): void {
    this.refreshState();
    if (this.stateValue === "half-open" && this.probeInFlightValue) {
      this.stateValue = "closed";
      this.probeInFlightValue = false;
      this.failures = [];
      this.openedAtValue = undefined;
      return;
    }
    // A normal success does not erase failures in the sliding window.
  }

  /** Record a failed request. */
  public recordFailure(): void {
    this.refreshState();
    if (this.stateValue === "half-open") {
      if (!this.probeInFlightValue) {
        return;
      }
      this.probeInFlightValue = false;
      this.openCircuit();
      return;
    }
    if (this.stateValue === "open") {
      return;
    }
    const now = this.clock();
    this.failures = this.failures.filter((time) => time > now - this.windowMs);
    this.failures.push(now);
    if (this.failures.length >= this.threshold) {
      this.openCircuit();
    }
  }

  public onSuccess(): void {
    this.recordSuccess();
  }

  public onFailure(): void {
    this.recordFailure();
  }

  /** Execute an operation only when the circuit permits it. */
  public async execute<T>(operation: () => T | Promise<T>): Promise<T> {
    if (!this.allowRequest()) {
      throw new RateCircuitOpenError();
    }
    try {
      const result = await operation();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }

  public snapshot(): RateCircuitBreakerSnapshot {
    this.refreshState();
    const failuresInWindow = this.failures.filter(
      (time) => time > this.clock() - this.windowMs,
    ).length;
    return {
      state: this.stateValue,
      failuresInWindow,
      probeInFlight: this.probeInFlightValue,
      ...(this.openedAtValue === undefined
        ? {}
        : { openedAt: this.openedAtValue }),
      ...(this.openedAtValue === undefined
        ? {}
        : { nextProbeAt: this.openedAtValue + this.cooldownMs }),
    };
  }

  public reset(): void {
    this.stateValue = "closed";
    this.failures = [];
    this.openedAtValue = undefined;
    this.probeInFlightValue = false;
  }

  private openCircuit(): void {
    this.stateValue = "open";
    this.openedAtValue = this.clock();
    this.probeInFlightValue = false;
  }

  private refreshState(): void {
    if (this.stateValue !== "open" || this.openedAtValue === undefined) {
      return;
    }
    if (this.clock() - this.openedAtValue >= this.cooldownMs) {
      this.stateValue = "half-open";
      this.probeInFlightValue = false;
    }
  }
}

export class RateCircuitOpenError extends Error {
  public constructor() {
    super("rate circuit breaker is open");
    this.name = "RateCircuitOpenError";
  }
}

export default RateCircuitBreaker;

